<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {request} from './model';
import {roomRacks,freeRackUnits} from './devicePlacement';
import type {State,Device} from './model';
const props=defineProps<{state:State;device:Device;compact?:boolean;disabled?:boolean;preferredRackId?:string}>();
const emit=defineEmits<{saved:[state:State];busy:[value:boolean]}>();
const busy=ref(false),open=ref(false),error=ref(''),rackId=ref(''),startU=ref(1),undo=ref<{device:Device;revision:number}>();
const racks=computed(()=>roomRacks(props.state,props.device.moduleId));
const rackModules=computed(()=>props.state.modules.filter(m=>racks.value.some(r=>r.moduleId===m.id)));
const height=computed(()=>props.state.models.find(m=>m.id===props.device.modelId)?.uHeight||0);
const freeUs=computed(()=>freeRackUnits(props.state,props.device,rackId.value));
watch(freeUs,values=>{if(!values.includes(startU.value))startU.value=values[0]||1});
watch(()=>props.device.id,()=>{open.value=false;undo.value=undefined;error.value=''});
function choose(){rackId.value=racks.value.find(r=>r.id===props.preferredRackId)?.id||props.device.rackId||racks.value.find(r=>r.moduleId===props.device.moduleId)?.id||racks.value[0]?.id||'';startU.value=props.device.startU||1;open.value=!open.value}
async function place(rack:string,u:number,restoring=false){if(busy.value||props.disabled)return;const previous={...props.device};busy.value=true;emit('busy',true);error.value='';try{const next=restoring?await request<State>('/devices/'+props.device.id,'PUT',{revision:undo.value!.revision,device:undo.value!.device}):await request<State>('/devices/'+props.device.id+'/placement','POST',{revision:props.state.revision,rackId:rack,startU:u});undo.value=restoring?undefined:{device:previous,revision:next.revision};emit('saved',next);open.value=false}catch(e){error.value=(e as Error).message}finally{busy.value=false;emit('busy',false)}}
</script>
<template><div :class="['device-quick-actions',{'is-compact':compact}]"><div class="device-placement-buttons"><button v-if="device.rackId" type="button" class="secondary quick-placement-unrack" :disabled="busy||disabled" :aria-label="compact?'下架 '+device.name:'移至待上架区'" :aria-keyshortcuts="compact?undefined:'Alt+u'" title="移至待上架区（Alt+U）" @click="place('',0)">{{compact?'下架':'移至待上架区'}}<kbd v-if="!compact">Alt U</kbd></button><button type="button" :class="device.rackId?'text-button':'secondary'" :disabled="busy||disabled||!height" :aria-expanded="open" :aria-label="(device.rackId?'调整机位 ':'上架 ')+device.name" :title="height?'直接选择机柜与空闲U位':'请先在型号库确认设备U高'" @click="choose">{{device.rackId?'调整机位':'选择机位上架'}}</button></div><p v-if="!height&&!device.rackId" class="field-note">型号U高待确认，确认后可上架。</p><form v-if="open" class="quick-placement-form" @submit.prevent="freeUs.includes(startU)&&place(rackId,startU)"><label>目标机柜<select v-model="rackId" aria-label="快捷上架机柜" required :disabled="busy"><optgroup v-for="m in rackModules" :key="m.id" :label="m.name"><option v-for="r in racks.filter(r=>r.moduleId===m.id)" :key="r.id" :value="r.id">{{m.name}} / {{r.name}}（{{r.side}}列）</option></optgroup></select></label><label>空闲起始U<select v-model.number="startU" aria-label="快捷上架U位" :disabled="busy||!freeUs.length"><option v-for="u in freeUs" :key="u" :value="u">U{{u}}–{{u+height-1}}</option></select></label><p v-if="!freeUs.length" class="field-note">该机柜没有连续空闲U位，请更换机柜。</p><div class="quick-placement-submit"><button class="primary" :disabled="busy||disabled||!freeUs.length">确认机位</button><button type="button" class="text-button" :disabled="busy" @click="open=false">取消</button></div></form><p v-if="error" class="error-banner" role="alert">{{error}}</p><div v-if="undo&&undo.revision===state.revision" class="placement-undo" role="status">机位已更新<button type="button" class="text-button" :disabled="busy||disabled" @click="place(undo!.device.rackId,undo!.device.startU,true)">撤销机位变更</button></div></div></template>
